<script setup>
import { onMounted, ref } from 'vue'
import loyaltyApi from '@/api/loyalty.api'
import CustomerQuickSearch from '@/components/loyalty/CustomerQuickSearch.vue'
import { getApiErrorMessage } from '@/api/error'
import { useAuthStore } from '@/store/auth'
const auth=useAuthStore(), rewards=ref([]),selectedCustomer=ref(null),error=ref(''),form=ref({name:'',description:'',reward_type:'fixed_discount',required_points:1,value:0,is_enabled:true})
async function load(){try{rewards.value=await loyaltyApi.rewards()}catch(e){error.value=getApiErrorMessage(e)}}
async function create(){try{await loyaltyApi.createReward(form.value);form.value={name:'',description:'',reward_type:'fixed_discount',required_points:1,value:0,is_enabled:true};await load()}catch(e){error.value=getApiErrorMessage(e)}}
async function redeem(reward){if(!selectedCustomer.value){error.value='ابتدا مشتری را انتخاب کنید.';return}if(!confirm(`پاداش «${reward.name}» با کسر ${reward.required_points} امتیاز صادر شود؟`))return;try{await loyaltyApi.redeemReward(reward.id,{customer_id:selectedCustomer.value.customer_id,idempotency_key:`reward-${crypto.randomUUID()}`});selectedCustomer.value=null;alert('پاداش با موفقیت صادر شد.')}catch(e){error.value=getApiErrorMessage(e)}}
onMounted(load)
</script>
<template><div class="loyalty-page"><header class="loyalty-header"><div><h1>جوایز و پاداش‌ها</h1><p>صدور پاداش فقط به‌صورت اپراتوری، صریح و قابل رهگیری انجام می‌شود.</p></div></header><p v-if="error" class="loyalty-error">{{error}}</p><CustomerQuickSearch v-model="selectedCustomer"/><div class="loyalty-grid-2"><section class="loyalty-card loyalty-table-wrap"><h2>کاتالوگ پاداش</h2><table class="loyalty-table"><thead><tr><th>نام</th><th>نوع</th><th>امتیاز لازم</th><th>ارزش</th><th></th></tr></thead><tbody><tr v-for="r in rewards" :key="r.id"><td>{{r.name}}</td><td>{{r.reward_type}}</td><td>{{Number(r.required_points).toLocaleString('fa-IR')}}</td><td>{{Number(r.value).toLocaleString('fa-IR')}}</td><td><button class="admin-button admin-button--secondary admin-button--sm" :disabled="!r.is_enabled" @click="redeem(r)">صدور</button></td></tr><tr v-if="!rewards.length"><td colspan="5" class="loyalty-empty">هنوز پاداشی ثبت نشده است.</td></tr></tbody></table></section><form class="loyalty-card loyalty-form" @submit.prevent="create"><h2>پاداش جدید</h2><label>نام<input v-model="form.name" required></label><label>نوع<select v-model="form.reward_type"><option value="fixed_discount">تخفیف ثابت</option><option value="percent_discount">تخفیف درصدی</option><option value="wallet_credit">اعتبار کیف پول</option><option value="product">محصول</option></select></label><label>امتیاز لازم<input v-model.number="form.required_points" type="number" min="1" required></label><label>ارزش<input v-model="form.value" type="number" min="0"></label><label>توضیحات<textarea v-model="form.description"></textarea></label><button class="admin-button admin-button--primary">ایجاد پاداش</button></form></div></div></template>
